// RSS-FEEDS LADEN & VORFILTERN
// n8n Code Node: "Run Once for All Items"
// Ziel:
// 1. RSS-Feeds laden
// 2. Direkte Aktiennews erkennen: type = stock_news
// 3. Markt-/Makro-News erkennen: type = market_news
// 4. Breitere Kandidaten erkennen: type = market_candidate
// 5. Nur eindeutig irrelevanten Unsinn ausschließen
// 6. KI bewertet später final: hoch / mittel / niedrig / irrelevant

const feeds = [
  { url: 'https://www.tagesschau.de/xml/rss2', name: 'Tagesschau' },
  { url: 'https://www.tagesschau.de/wirtschaft/index~rss2.xml', name: 'Tagesschau Wirtschaft' },
  { url: 'https://www.welt.de/feeds/latest.rss', name: 'Die Welt' },
  { url: 'https://www.spiegel.de/wirtschaft/index.rss', name: 'Spiegel Wirtschaft' },
  { url: 'https://www.stern.de/feed/standard/all/', name: 'Stern' },
  { url: 'https://newsfeed.zeit.de/wirtschaft/index', name: 'Zeit Wirtschaft' },
  { url: 'https://www.n-tv.de/wirtschaft/rss', name: 'n-tv Wirtschaft' }
];

// Direkte Aktien-Watchlist
const watchlist = [
  {
    ticker: 'SAP.DE',
    name: 'SAP SE',
    patterns: [
