    ],
    excludePatterns: []
  },
  {
    ticker: 'BASF.DE',
    name: 'BASF SE',
    patterns: [
      /\bBASF\b/i,
      /\bBASF SE\b/i
    ],
    excludePatterns: []
  },
  {
    ticker: 'ALV.DE',
    name: 'Allianz SE',
    patterns: [
      /\bAllianz\b/i,
      /\bAllianz SE\b/i
    ],
