// ============================================================
// KI-BEWERTUNG AUFBEREITEN – robust + debug
// Modus: runOnceForAllItems
// ============================================================

// ── 1. Alle Input-Items einlesen ───────────────────────────
const allItems = $input.all();
const sd = $getWorkflowStaticData('global');
const originals = sd.news_batch_originals || [];

// ── 2. KI-Rohantwort robust extrahieren ────────────────────
// Der OpenAI-Node gibt je nach Version/Modus unterschiedliche Strukturen aus.
// Wir durchsuchen alle bekannten Pfade und nehmen den längsten gültigen String.

function findLongestString(obj, depth = 0) {
  if (depth > 6) return '';
  if (typeof obj === 'string' && obj.length > 10) return obj;
  if (Array.isArray(obj)) {
    return obj.map(v => findLongestString(v, depth + 1))
              .reduce((a, b) => (b.length > a.length ? b : a), '');
  }
  if (obj && typeof obj === 'object') {
    return Object.values(obj)
                 .map(v => findLongestString(v, depth + 1))
                 .reduce((a, b) => (b.length > a.length ? b : a), '');
  }
  return '';
}

function extractRaw(ki) {
  const candidates = [
    // n8n OpenAI node v2.x Responses-Modus
    ki?.output?.[0]?.content?.[0]?.text,
    ki?.output?.[0]?.content?.[0]?.value,
    // output_text (direkt)
    ki?.output_text,
    // Chat-Completions klassisch
    ki?.choices?.[0]?.message?.content,
    ki?.message?.content,
    // Einfache Felder
    ki?.text,
    ki?.response,
    ki?.content,
    ki?.data,
    ki?.result,
    // output als String
    typeof ki?.output === 'string' ? ki.output : null,
    // output als Array von Strings
    Array.isArray(ki?.output) && typeof ki.output[0] === 'string' ? ki.output[0] : null,
  ].filter(v => typeof v === 'string' && v.trim().length > 5);

  if (candidates.length > 0) {
    // Längsten nehmen (wahrscheinlich die vollständige Antwort)
    return candidates.reduce((a, b) => (b.length > a.length ? b : a), '');
  }

  // Letzter Ausweg: rekursiv den längsten String im ganzen Objekt suchen
  return findLongestString(ki);
}

// ── 3. Alle Input-Items nach der Rohantwort durchsuchen ────
let raw = '';
let rawSource = 'nicht gefunden';
let availableKeys = [];

for (const item of allItems) {
  const ki = item.json;
  availableKeys = Object.keys(ki || {});
  const candidate = extractRaw(ki);
  if (candidate && candidate.length > raw.length) {
    raw = candidate;
    rawSource = 'gefunden in item ' + allItems.indexOf(item);
  }
}

// ── 4. JSON-Array aus Rohantwort extrahieren ───────────────
function parseKiArray(raw) {
  if (!raw) return null;

  // Markdown-Codeblöcke entfernen
  let cleaned = raw
    .replace(/^```json\s*/gm, '')
    .replace(/^```\s*/gm, '')
    .replace(/```$/gm, '')
    .trim();

  // Ersten vollständigen JSON-Array-Block finden
  const start = cleaned.indexOf('[');
  if (start === -1) return null;

  // Klammern zählen um das Ende zu finden
  let depth = 0;
  let end = -1;
  for (let i = start; i < cleaned.length; i++) {
    if (cleaned[i] === '[') depth++;
    else if (cleaned[i] === ']') {
      depth--;
      if (depth === 0) { end = i; break; }
    }
  }

  if (end === -1) return null;

  const jsonStr = cleaned.substring(start, end + 1);
  return JSON.parse(jsonStr); // wirft bei ungültigem JSON
}

let bewertungen = null;
let parseError = null;

try {
  bewertungen = parseKiArray(raw);
} catch(e) {
  parseError = e.message;
}

// ── 5. Debug-Output wenn Parsing fehlgeschlagen ────────────
if (!bewertungen || !Array.isArray(bewertungen) || bewertungen.length === 0) {
  return [{
    json: {
      debug_error: true,
      fehler: parseError || 'Kein JSON-Array gefunden',
      raw_preview: raw.substring(0, 500),
      raw_length: raw.length,
      raw_source: rawSource,
      available_keys: availableKeys,
      input_count: allItems.length,
      originals_count: originals.length,
      hinweis: 'Prüfe im KI-Node Output: {{ JSON.stringify($json) }}'
    }
  }];
}

// ── 6. Bewertungs-Map über id aufbauen ─────────────────────
const bewertungMap = new Map();
for (const b of bewertungen) {
  // id kann Zahl oder String sein
  bewertungMap.set(String(b.id), b);
  // Fallback: news_key falls vorhanden
  if (b.news_key) bewertungMap.set(String(b.news_key), b);
}

// ── 7. Originaldaten + Bewertungen zusammenführen ──────────
const result = originals.map((original, i) => {
  const idKey = String(i);
  const newsKey = original.news_key || original.link || (original.ticker + '|' + original.titel);

  const b = bewertungMap.get(idKey)
         || bewertungMap.get(newsKey)
         || null;

  // Nur echter Fallback wenn Bewertung wirklich fehlt (KI-Antwort war aber valide)
  const fallback = {
    relevanz:      'unbekannt',
    sentiment:     'unklar',
    kurswirkung:   'unklar',
    bezug:         `ID ${i} nicht in KI-Antwort (${bewertungen.length} Bewertungen erhalten)`,
    verwendung:    'speichern',
    score:         0,
    dringlichkeit: 'beobachten',
    begruendung:   `Keine Bewertung für ID ${i} gefunden`
  };

  const bw = b || fallback;

  return {
    json: {
      // Originaldaten
      news_key:     newsKey,
      type:         original.type         || 'unknown',
      ticker:       original.ticker       || 'MARKT',
      name:         original.name         || '',
      titel:        original.titel        || '',
      beschreibung: original.beschreibung || '',
      quelle:       original.quelle       || '',
      datum:        original.datum        || '',
      datum_iso:    original.datum_iso    || '',
      link:         original.link         || '',
      vorfilter:    original.vorfilter    || '',
      matchGrund:   original.matchGrund   || '',
      // KI-Bewertung
      relevanz:      String(bw.relevanz      || 'unbekannt'),
      sentiment:     String(bw.sentiment     || 'unklar'),
      kurswirkung:   String(bw.kurswirkung   || 'unklar'),
      bezug:         String(bw.bezug         || ''),
      verwendung:    String(bw.verwendung    || 'speichern'),
      score:         Math.max(0, Math.min(100, Number(bw.score) || 0)),
      dringlichkeit: String(bw.dringlichkeit || 'beobachten'),
      begruendung:   String(bw.begruendung   || ''),
      ki_rohantwort: raw.substring(0, 2000),
      // News-Wirkungsfelder
      betroffene_ticker:     Array.isArray(bw.betroffene_ticker)
                               ? JSON.stringify(bw.betroffene_ticker)
                               : '[]',
      wirkungsebene:         String(bw.wirkungsebene         || 'unklar'),
      wirkungsrichtung:      String(bw.wirkungsrichtung      || 'unklar'),
      wirkung_staerke:       String(bw.wirkung_staerke       || 'niedrig'),
      begruendung_tickerbezug: String(bw.begruendung_tickerbezug || '')
    }
  };
});

return result;

function esc(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

const relevanz = String($json.relevanz || 'unbekannt').toUpperCase();
const titel = $json.titel || 'Ohne Titel';
const type = $json.type || 'unbekannt';
const ticker = $json.ticker || '';
const name = $json.name || '';
const bezug = $json.bezug || 'unklar';
const sentiment = $json.sentiment || 'unklar';
const kurswirkung = $json.kurswirkung || 'unklar';
const score = $json.score ?? '';
const dringlichkeit = $json.dringlichkeit || 'beobachten';
const begruendung = $json.begruendung || '';
const link = $json.link || '';

const body =
`🚨 Aktien-Radar: ${relevanz}

${titel}

Typ: ${type}
Ticker: ${ticker}
Name: ${name}
Bezug: ${bezug}
Sentiment: ${sentiment}
Kurswirkung: ${kurswirkung}
Score: ${score}
Dringlichkeit: ${dringlichkeit}

${begruendung}

${link}`;

const formatted_body =
`<b>🚨 Aktien-Radar: ${esc(relevanz)}</b><br>
<b>${esc(titel)}</b><br><br>
<b>Typ:</b> ${esc(type)}<br>
<b>Ticker:</b> ${esc(ticker)}<br>
<b>Name:</b> ${esc(name)}<br>
<b>Bezug:</b> ${esc(bezug)}<br>
<b>Sentiment:</b> ${esc(sentiment)}<br>
<b>Kurswirkung:</b> ${esc(kurswirkung)}<br>
<b>Score:</b> ${esc(score)}<br>
<b>Dringlichkeit:</b> ${esc(dringlichkeit)}<br><br>
<i>${esc(begruendung)}</i><br><br>
${link ? `<a href="${esc(link)}">Quelle öffnen</a>` : ''}`;

return {
  json: {
    ...$json,
    matrixTxnId: `${$execution.id}-news-${$itemIndex}-${Date.now()}`,
    matrixPayload: {
      msgtype: 'm.text',
      format: 'org.matrix.custom.html',
      body,
      formatted_body
    }
  }
};
